    "v44": "map_mask_shifted"
  },
  "struct_hints": [
    {
      "offset": 166,
      "meaning": "uint8_t status_flags: bit 0x20 causes early return and bit 0x40 selects alternate path"
    },
    {
      "offset": 154,
      "meaning": "uint8_t skip/error or pending flag; nonzero suppresses processing"
    },
    {
      "offset": 152,
      "meaning": "uint16_t countdown/retry or packet-state counter; nonzero decrements and returns"
    },
    {
      "offset": 136,
      "meaning": "uint16_t current context/channel index"
    },
    {
      "offset": 138,
