    },
    {
      "offset": 174,
      "meaning": "uint16_t selection or channel-map bitmask"
    },
    {
      "offset": 177,
      "meaning": "uint8_t selection range lower bound"
    },
    {
      "offset": 178,
      "meaning": "uint8_t selection range upper bound"
